api.MapPost("/operations/{id:guid}/adjustments", async (Guid id, CustomsValueAdjustmentRequest request, HttpContext ctx, SaceDbContext db) => { if (!await db.TradeOperations.AnyAsync(x => x.Id == id)) return Results.NotFound(); if (request.Amount < 0 || string.IsNullOrWhiteSpace(request.Concept) || string.IsNullOrWhiteSpace(request.Currency)) return Results.BadRequest(new ApiError(400, "VALIDATION_ERROR", "Concepto, moneda e importe no negativo son obligatorios.", new { })); if (request.SourceDocumentId.HasValue && !await db.OperationDocuments.AnyAsync(x => x.Id == request.SourceDocumentId && x.TradeOperationId == id)) return Results.BadRequest(new ApiError(400, "INVALID_SOURCE_DOCUMENT", "El documento fuente no pertenece al expediente.", new { })); var item = new CustomsValueAdjustment { TradeOperationId = id, Concept = request.Concept.Trim(), Description = request.Description, Amount = request.Amount, Currency = request.Currency.Trim().ToUpperInvariant(), AdjustmentType = request.AdjustmentType, LegalQualificationStatus = request.LegalQualificationStatus, SourceDocumentId = request.SourceDocumentId }; db.CustomsValueAdjustments.Add(item); db.SystemAuditLogs.Add(Log(ctx.User.UserId(), "CUSTOMS_VALUE_ADJUSTMENT_CREATED", "CustomsValueAdjustment", item.Id, $"{item.Concept}: {item.Amount} {item.Currency}; {item.AdjustmentType}/{item.LegalQualificationStatus}.")); await db.SaveChangesAsync(); return Results.Created($"/api/operations/{id}/adjustments/{item.Id}", item); });
api.MapPost("/audit-results/{id:guid}/manual-review", async (Guid id, ManualReviewRequest request, HttpContext ctx, SaceDbContext db) => { var result = await db.AuditResults.Include(x => x.NormativeRule).SingleOrDefaultAsync(x => x.Id == id && x.Outcome != null); if (result is null) return Results.NotFound(); if (request.ManualOutcome == LegalOutcome.NOT_APPLICABLE || request.ManualOutcome == LegalOutcome.MANUAL_REVIEW || string.IsNullOrWhiteSpace(request.Comment)) return Results.BadRequest(new ApiError(400, "VALIDATION_ERROR", "Seleccione un dictamen final y capture el comentario de revisión.", new { })); result.ManualOutcome = request.ManualOutcome; result.ReviewComment = request.Comment.Trim(); result.ReviewerUserId = ctx.User.UserId(); result.ReviewedAt = DateTime.UtcNow; db.SystemAuditLogs.Add(Log(ctx.User.UserId(), "MANUAL_REVIEW_COMPLETED", "AuditResult", result.Id, $"{result.RuleId}: automático {result.Outcome}; humano {result.ManualOutcome}.")); await db.SaveChangesAsync(); return Results.Ok(result); });

api.MapPost("/operations/{id:guid}/documents", async (Guid id, Guid documentTypeId, IFormFile file, HttpContext ctx, SaceDbContext db, IDocumentProcessingService processing, CancellationToken ct) => { var type = await db.DocumentTypes.FindAsync([documentTypeId], ct); if (type is null) return Results.NotFound(new ApiError(404, "NOT_FOUND", "Tipo documental no localizado.", new { })); var result = await processing.UploadBulkAsync(id, [file], [type.Code], true, ctx.User.UserId(), ct); var item = result.Files[0]; return item.Status == "Accepted" ? Results.Created($"/api/operations/{id}/documents/{item.DocumentId}", item) : Results.BadRequest(new ApiError(400, item.Code ?? "INVALID_FILE", item.Message ?? "Archivo rechazado.", new { item.DuplicateOf })); }).DisableAntiforgery();
