api.MapGet("/operations/{operationId:guid}/documents/{documentId:guid}", async (Guid operationId, Guid documentId, SaceDbContext db) => { var doc = await db.OperationDocuments.AsNoTracking().Include(x => x.DocumentType).Include(x => x.References).Include(x=>x.Fields).SingleOrDefaultAsync(x => x.Id == documentId && x.TradeOperationId == operationId); if (doc is null) return Results.NotFound(); var cove = await db.TradeOperations.Where(x => x.Id == operationId).Select(x => x.CoveNumber).SingleAsync(); return Results.Ok(new { document = doc, referenceComparisons = doc.References.Select(x => new { x.ReferenceType, x.Value, matchesOperation = x.ReferenceType == "COVE" && !string.IsNullOrWhiteSpace(cove) ? string.Equals(x.Value, cove, StringComparison.OrdinalIgnoreCase) : (bool?)null }) }); });
api.MapPatch("/operations/{operationId:guid}/documents/{documentId:guid}", async (Guid operationId, Guid documentId, UpdateDocumentRequest request, HttpContext ctx, SaceDbContext db) => { var doc = await db.OperationDocuments.Include(x => x.References).SingleOrDefaultAsync(x => x.Id == documentId && x.TradeOperationId == operationId); if (doc is null) return Results.NotFound(); doc.DocumentNumber=request.DocumentNumber; doc.DocumentDate=request.DocumentDate?.ToUniversalTime(); doc.SourceSystem=request.SourceSystem; doc.Notes=request.Notes; foreach(var reference in request.References ?? []) { var type=reference.ReferenceType.Trim().ToUpperInvariant(); var value=reference.Value.Trim().ToUpperInvariant(); if(value.Length>0 && !doc.References.Any(x=>x.ReferenceType==type && x.Value==value)) doc.References.Add(new DocumentReference { ReferenceType=type, Value=value, Source=reference.Source }); } db.SystemAuditLogs.Add(Log(ctx.User.UserId(), "DOCUMENT_METADATA_UPDATED", "OperationDocument", doc.Id, $"Metadata actualizada para {doc.OriginalFileName}.")); await db.SaveChangesAsync(); return Results.Ok(doc); });
