api.MapGet("/operations/{operationId:guid}/cross-validations", async (Guid operationId,SaceDbContext db,CancellationToken ct) => { if(!await db.TradeOperations.AnyAsync(x=>x.Id==operationId,ct))return Results.NotFound(new ApiError(404,"NOT_FOUND","Operación no localizada.",new{}));var rows=await db.CrossValidationResults.AsNoTracking().Where(x=>x.TradeOperationId==operationId).Include(x=>x.CrossValidationRule).Include(x=>x.SourceDocument).ThenInclude(x=>x!.DocumentType).Include(x=>x.TargetDocument).ThenInclude(x=>x!.DocumentType).Include(x=>x.SourceField).Include(x=>x.TargetField).OrderByDescending(x=>x.EvaluatedAt).ToListAsync(ct);return Results.Ok(rows.GroupBy(x=>x.RuleCode).Select(x=>x.First()).OrderBy(x=>x.CrossValidationRule.Category).ThenBy(x=>x.RuleCode)); });
api.MapPost("/operations/{operationId:guid}/cross-validations/run", async (Guid operationId,HttpContext ctx,ICrossValidationEngine engine,CancellationToken ct) => { var rows=await engine.ExecuteAsync(operationId,null,ctx.User.UserId(),ct);return Results.Ok(new{operationId,evaluated=rows.Count,matches=rows.Count(x=>x.Outcome==CrossValidationOutcome.MATCH),mismatches=rows.Count(x=>x.Outcome==CrossValidationOutcome.MISMATCH),insufficientEvidence=rows.Count(x=>x.Outcome==CrossValidationOutcome.INSUFFICIENT_EVIDENCE),manualReview=rows.Count(x=>x.Outcome==CrossValidationOutcome.MANUAL_REVIEW),notApplicable=rows.Count(x=>x.Outcome==CrossValidationOutcome.NOT_APPLICABLE)}); });
api.MapGet("/operations/{operationId:guid}/valuation", async (Guid operationId,SaceDbContext db,CancellationToken ct) => { if(!await db.TradeOperations.AnyAsync(x=>x.Id==operationId,ct))return Results.NotFound(new ApiError(404,"NOT_FOUND","Operación no localizada.",new{}));var result=await db.CustomsValuationCalculations.AsNoTracking().Where(x=>x.TradeOperationId==operationId).Include(x=>x.Components).ThenInclude(x=>x.PrimaryDocument).Include(x=>x.Components).ThenInclude(x=>x.Evidence).ThenInclude(x=>x.OperationDocument).Include(x=>x.Components).ThenInclude(x=>x.Evidence).ThenInclude(x=>x.DocumentField).OrderByDescending(x=>x.CalculationVersion).FirstOrDefaultAsync(ct);return result is null?Results.NoContent():Results.Ok(result); });
