api.MapGet("/regulatory-requirements/{id:guid}", async (Guid id,SaceDbContext db,CancellationToken ct) => {var item=await db.RegulatoryRequirements.AsNoTracking().AsSplitQuery().Include(x=>x.Conditions).Include(x=>x.EvidenceRequirements).Include(x=>x.TariffEntries).Include(x=>x.SourceCitations).ThenInclude(x=>x.OfficialSourceCitation).ThenInclude(x=>x.OfficialLegalSourceVersion).ThenInclude(x=>x.OfficialLegalSource).FirstOrDefaultAsync(x=>x.Id==id,ct);return item is null?Results.NotFound(new ApiError(404,"NOT_FOUND","Requisito regulatorio no localizado.",new{})):Results.Ok(item);});
api.MapPost("/regulatory-requirements", async (RegulatoryRequirementRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct) => {
  var error=await ValidateRegulatoryRequest(request,db,ct);if(error is not null)return Results.BadRequest(new ApiError(400,"VALIDATION_ERROR",error,new{}));
  var code=request.Code.Trim().ToUpperInvariant();var version=(await db.RegulatoryRequirements.Where(x=>x.Code==code).MaxAsync(x=>(int?)x.Version,ct)??0)+1;var item=new RegulatoryRequirement{Code=code,Version=version,Status=RegulatoryRequirementStatus.DRAFT};ApplyRegulatoryRequest(item,request);db.RegulatoryRequirements.Add(item);db.SystemAuditLogs.Add(Log(ctx.User.UserId(),"REGULATORY_REQUIREMENT_CREATED",nameof(RegulatoryRequirement),item.Id,$"{item.Code} v{item.Version} DRAFT."));await db.SaveChangesAsync(ct);return Results.Created($"/api/regulatory-requirements/{item.Id}",item);
});
api.MapPut("/regulatory-requirements/{id:guid}", async (Guid id,RegulatoryRequirementRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct) => {
  var item=await db.RegulatoryRequirements.Include(x=>x.Conditions).Include(x=>x.EvidenceRequirements).FirstOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Results.NotFound();if(item.Status!=RegulatoryRequirementStatus.DRAFT)return Results.BadRequest(new ApiError(400,"VERIFIED_IMMUTABLE","Una versión VERIFIED no se edita; cree una nueva versión.",new{}));
  var error=await ValidateRegulatoryRequest(request,db,ct);if(error is not null)return Results.BadRequest(new ApiError(400,"VALIDATION_ERROR",error,new{}));if(!item.Code.Equals(request.Code.Trim(),StringComparison.OrdinalIgnoreCase))return Results.BadRequest(new ApiError(400,"CODE_IMMUTABLE","El código no puede cambiar dentro de una versión.",new{}));
  ApplyRegulatoryScalars(item,request);SyncRegulatoryChildren(item,request,db);item.UpdatedAt=DateTime.UtcNow;db.SystemAuditLogs.Add(Log(ctx.User.UserId(),"REGULATORY_REQUIREMENT_UPDATED",nameof(RegulatoryRequirement),item.Id,$"{item.Code} v{item.Version} DRAFT."));await db.SaveChangesAsync(ct);return Results.Ok(item);
});
api.MapPost("/regulatory-requirements/{id:guid}/version", async (Guid id,RegulatoryRequirementRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct) => {
  var source=await db.RegulatoryRequirements.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);if(source is null)return Results.NotFound();var error=await ValidateRegulatoryRequest(request,db,ct);if(error is not null)return Results.BadRequest(new ApiError(400,"VALIDATION_ERROR",error,new{}));if(!source.Code.Equals(request.Code.Trim(),StringComparison.OrdinalIgnoreCase))return Results.BadRequest(new ApiError(400,"CODE_IMMUTABLE","La nueva versión debe conservar el código.",new{}));
  var version=(await db.RegulatoryRequirements.Where(x=>x.Code==source.Code).MaxAsync(x=>(int?)x.Version,ct)??0)+1;var item=new RegulatoryRequirement{Code=source.Code,Version=version,Status=RegulatoryRequirementStatus.DRAFT};ApplyRegulatoryRequest(item,request);db.RegulatoryRequirements.Add(item);db.SystemAuditLogs.Add(Log(ctx.User.UserId(),"REGULATORY_REQUIREMENT_VERSIONED",nameof(RegulatoryRequirement),item.Id,$"{item.Code}: v{source.Version} → v{item.Version} DRAFT."));await db.SaveChangesAsync(ct);return Results.Created($"/api/regulatory-requirements/{item.Id}",item);
});
api.MapPost("/regulatory-requirements/{id:guid}/verify",async(Guid id,VerifyRegulatoryRequirementRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{
  var item=await db.RegulatoryRequirements.Include(x=>x.SourceCitations).ThenInclude(x=>x.OfficialSourceCitation).ThenInclude(x=>x.OfficialLegalSourceVersion).FirstOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Results.NotFound();if(item.Status!=RegulatoryRequirementStatus.DRAFT)return Results.BadRequest(new ApiError(400,"INVALID_STATUS","Sólo una versión DRAFT puede verificarse.",new{}));
  if(item.SourceCitations.Count==0||item.SourceCitations.Any(x=>x.OfficialSourceCitation.OfficialLegalSourceVersion.VerificationStatus!=SourceVerificationStatus.VERIFIED))return Results.BadRequest(new ApiError(400,"UNVERIFIED_SOURCE","Todo requisito VERIFIED requiere al menos una cita de una versión oficial VERIFIED.",new{}));
  var overlap=await db.RegulatoryRequirements.AnyAsync(x=>x.Id!=id&&x.Code==item.Code&&x.Status==RegulatoryRequirementStatus.VERIFIED&&(item.EffectiveTo==null||x.EffectiveFrom==null||x.EffectiveFrom<=item.EffectiveTo)&&(x.EffectiveTo==null||item.EffectiveFrom==null||item.EffectiveFrom<=x.EffectiveTo),ct);if(overlap)return Results.BadRequest(new ApiError(400,"OVERLAPPING_EFFECTIVE_PERIOD","La vigencia se traslapa con otra versión VERIFIED.",new{}));
  item.Status=RegulatoryRequirementStatus.VERIFIED;item.VerificationLevel=request.VerificationLevel;item.VerifiedBy=ctx.User.UserId();item.VerifiedAt=DateTime.UtcNow;item.UpdatedAt=DateTime.UtcNow;db.SystemAuditLogs.Add(Log(ctx.User.UserId(),"REGULATORY_REQUIREMENT_VERIFIED",nameof(RegulatoryRequirement),item.Id,$"{item.Code} v{item.Version}; {request.VerificationLevel}."));await db.SaveChangesAsync(ct);return Results.Ok(item);
});

api.MapGet("/legal-sources",async(SaceDbContext db,CancellationToken ct)=>Results.Ok(await db.OfficialLegalSources.AsNoTracking().Select(x=>new{x.Id,x.Code,x.Title,x.SourceType,x.Authority,x.OfficialUrl,x.Status,x.CreatedAt,x.UpdatedAt,versions=x.Versions.Count,citations=x.Versions.SelectMany(v=>v.Citations).Count(),requirements=x.Versions.SelectMany(v=>v.Citations).SelectMany(c=>c.Requirements).Select(r=>r.RegulatoryRequirementId).Distinct().Count(),tariffEntries=x.Versions.SelectMany(v=>v.Citations).SelectMany(c=>c.TariffEntries).Count()}).OrderBy(x=>x.Code).ToListAsync(ct)));
api.MapGet("/legal-sources/{id:guid}",async(Guid id,SaceDbContext db,CancellationToken ct)=>{var item=await db.OfficialLegalSources.AsNoTracking().AsSplitQuery().Include(x=>x.Versions).ThenInclude(x=>x.Citations).ThenInclude(x=>x.Requirements).ThenInclude(x=>x.RegulatoryRequirement).Include(x=>x.Versions).ThenInclude(x=>x.Citations).ThenInclude(x=>x.TariffEntries).FirstOrDefaultAsync(x=>x.Id==id,ct);return item is null?Results.NotFound(new ApiError(404,"NOT_FOUND","Fuente oficial no localizada.",new{})):Results.Ok(item);});
api.MapPost("/legal-sources",async(OfficialLegalSourceRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(request.Code)||string.IsNullOrWhiteSpace(request.Title)||!RegulatoryCatalogRules.IsOfficialUrl(request.OfficialUrl))return Results.BadRequest(new ApiError(400,"VALIDATION_ERROR","Código, título y URL oficial HTTPS gob.mx son obligatorios.",new{}));var code=request.Code.Trim().ToUpperInvariant();if(await db.OfficialLegalSources.AnyAsync(x=>x.Code==code,ct))return Results.Conflict(new ApiError(409,"DUPLICATE_SOURCE","Ya existe una fuente con ese código.",new{}));var item=new OfficialLegalSource{Code=code,Title=request.Title.Trim(),SourceType=request.SourceType,Authority=request.Authority.Trim(),OfficialUrl=request.OfficialUrl.Trim()};db.OfficialLegalSources.Add(item);db.SystemAuditLogs.Add(Log(ctx.User.UserId(),"LEGAL_SOURCE_CREATED",nameof(OfficialLegalSource),item.Id,item.Code));await db.SaveChangesAsync(ct);return Results.Created($"/api/legal-sources/{item.Id}",item);});
api.MapPost("/legal-sources/{id:guid}/versions",async(Guid id,OfficialLegalSourceVersionRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{var source=await db.OfficialLegalSources.Include(x=>x.Versions).FirstOrDefaultAsync(x=>x.Id==id,ct);if(source is null)return Results.NotFound();if(!RegulatoryCatalogRules.IsOfficialUrl(request.OfficialUrl)||request.EffectiveTo.HasValue&&request.EffectiveTo<request.EffectiveFrom)return Results.BadRequest(new ApiError(400,"VALIDATION_ERROR","URL oficial o vigencia inválida.",new{}));var item=new OfficialLegalSourceVersion{OfficialLegalSourceId=id,Version=(source.Versions.Count==0?0:source.Versions.Max(x=>x.Version))+1,VersionLabel=request.VersionLabel.Trim(),DofPublicationCode=request.DofPublicationCode?.Trim(),PublicationDate=request.PublicationDate.ToUniversalTime(),EffectiveFrom=request.EffectiveFrom.ToUniversalTime(),EffectiveTo=request.EffectiveTo?.ToUniversalTime(),OfficialUrl=request.OfficialUrl.Trim(),Sha256=request.Sha256?.Trim().ToLowerInvariant(),VerificationNotes=request.VerificationNotes?.Trim()};foreach(var c in request.Citations??[])item.Citations.Add(new(){CitationType=c.CitationType,CitationLabel=c.CitationLabel.Trim(),Article=c.Article?.Trim(),RuleNumber=c.RuleNumber?.Trim(),Annex=c.Annex?.Trim(),Section=c.Section?.Trim(),Subsection=c.Subsection?.Trim(),Numeral=c.Numeral?.Trim(),ExactReferenceText=c.ExactReferenceText?.Trim(),OfficialUrl=(c.OfficialUrl??request.OfficialUrl).Trim()});db.OfficialLegalSourceVersions.Add(item);db.SystemAuditLogs.Add(Log(ctx.User.UserId(),"LEGAL_SOURCE_VERSION_CREATED",nameof(OfficialLegalSourceVersion),item.Id,$"{source.Code} v{item.Version}."));await db.SaveChangesAsync(ct);return Results.Created($"/api/legal-sources/{id}",item);});
api.MapPost("/legal-sources/{id:guid}/verify",async(Guid id,VerifyLegalSourceRequest request,HttpContext ctx,SaceDbContext db,CancellationToken ct)=>{var source=await db.OfficialLegalSources.Include(x=>x.Versions).FirstOrDefaultAsync(x=>x.Id==id,ct);if(source is null)return Results.NotFound();var version=request.VersionId.HasValue?source.Versions.FirstOrDefault(x=>x.Id==request.VersionId):source.Versions.OrderByDescending(x=>x.Version).FirstOrDefault();if(version is null)return Results.BadRequest(new ApiError(400,"MISSING_VERSION","La fuente no tiene una versión verificable.",new{}));if(!RegulatoryCatalogRules.IsOfficialUrl(version.OfficialUrl))return Results.BadRequest(new ApiError(400,"UNOFFICIAL_URL","La versión no apunta a una URL oficial HTTPS gob.mx.",new{}));version.VerificationStatus=SourceVerificationStatus.VERIFIED;version.VerifiedBy=ctx.User.UserId();version.VerifiedAt=DateTime.UtcNow;version.VerificationNotes=request.VerificationNotes?.Trim()??version.VerificationNotes;source.Status=SourceVerificationStatus.VERIFIED;source.UpdatedAt=DateTime.UtcNow;db.SystemAuditLogs.Add(Log(ctx.User.UserId(),"LEGAL_SOURCE_VERIFIED",nameof(OfficialLegalSourceVersion),version.Id,$"{source.Code} {version.VersionLabel}."));await db.SaveChangesAsync(ct);return Results.Ok(version);});
api.MapGet("/legal-sources/{id:guid}/diff",async(Guid id,Guid? fromVersionId,Guid? toVersionId,SaceDbContext db,IRegulatoryCatalogDiffService service,CancellationToken ct)=>{var versions=await db.OfficialLegalSourceVersions.AsNoTracking().Where(x=>x.OfficialLegalSourceId==id).OrderByDescending(x=>x.Version).Select(x=>x.Id).ToListAsync(ct);var to=toVersionId??versions.FirstOrDefault();var from=fromVersionId??versions.Skip(1).FirstOrDefault();if(from==Guid.Empty||to==Guid.Empty)return Results.BadRequest(new ApiError(400,"INSUFFICIENT_VERSIONS","Se requieren dos versiones para comparar.",new{}));return Results.Ok(await service.CompareAsync(from,to,ct));});
