api.MapGet("/findings", async (FindingStatus? status, Severity? severity, CorrectionResponsible? responsible, string? period, SaceDbContext db) => { var q = db.Findings.AsNoTracking().Include(x => x.TradeOperation).Include(x => x.DocumentType).AsQueryable(); if (status.HasValue) q = q.Where(x => x.Status == status); if (severity.HasValue) q = q.Where(x => x.Severity == severity); if (responsible.HasValue) q = q.Where(x => x.CorrectionResponsible == responsible); if (!string.IsNullOrWhiteSpace(period)) q = q.Where(x => x.TradeOperation.Period == period); return Results.Ok(await q.OrderByDescending(x => x.CreatedAt).Select(x => new { x.Id, x.Number, x.TradeOperationId, x.TradeOperation.Folio, x.TradeOperation.PedimentoNumber, document = x.DocumentType.Name, x.RuleId, x.Description, x.Severity, x.CorrectionResponsible, x.Status, x.CreatedAt }).ToListAsync()); });
api.MapGet("/findings/{id:guid}", async (Guid id, SaceDbContext db) => { var item = await db.Findings.AsNoTracking().Include(x => x.TradeOperation).Include(x => x.DocumentType).Include(x => x.History).SingleOrDefaultAsync(x => x.Id == id); return item is null ? Results.NotFound() : Results.Ok(item); });
api.MapPatch("/findings/{id:guid}/status", async (Guid id, ChangeFindingStatusRequest request, HttpContext ctx, SaceDbContext db) => { var finding = await db.Findings.Include(x => x.History).SingleOrDefaultAsync(x => x.Id == id); if (finding is null) return Results.NotFound(); var valid = (finding.Status, request.Status) is (FindingStatus.Pending, FindingStatus.InCorrection) or (FindingStatus.InCorrection, FindingStatus.Resolved); if (!valid) return Results.BadRequest(new ApiError(400, "INVALID_TRANSITION", $"No se permite cambiar de {finding.Status} a {request.Status}.", new { })); var previous = finding.Status; finding.Status = request.Status; finding.UpdatedAt = DateTime.UtcNow; if (request.Status == FindingStatus.Resolved) finding.ResolvedAt = DateTime.UtcNow; db.FindingHistories.Add(new FindingHistory { FindingId = finding.Id, PreviousStatus = previous, NewStatus = request.Status, Comment = request.Comment ?? "Estado actualizado.", ChangedBy = ctx.User.UserId() }); db.SystemAuditLogs.Add(Log(ctx.User.UserId(), "FINDING_STATUS_CHANGED", "Finding", finding.Id, $"{previous} → {request.Status}")); await db.SaveChangesAsync(); return Results.Ok(new { finding.Id, finding.Status }); });
api.MapPost("/findings/{id:guid}/correction", async (Guid id, IFormFile file, HttpContext ctx, SaceDbContext db, IDocumentProcessingService processing, IAuditEngine engine, CancellationToken ct) => { var finding = await db.Findings.Include(x => x.DocumentType).SingleOrDefaultAsync(x => x.Id == id, ct); if (finding is null) return Results.NotFound(); if (finding.Status == FindingStatus.Resolved) return Results.BadRequest(new ApiError(400, "INVALID_TRANSITION", "El hallazgo ya está resuelto.", new { })); var uploaded = await processing.UploadBulkAsync(finding.TradeOperationId, [file], [finding.DocumentType.Code], false, ctx.User.UserId(), ct); var item = uploaded.Files[0]; if (item.Status != "Accepted") return Results.BadRequest(new ApiError(400, item.Code ?? "INVALID_FILE", item.Message ?? "Archivo rechazado.", new { })); if (finding.Status == FindingStatus.Pending) { db.FindingHistories.Add(new FindingHistory { FindingId = finding.Id, PreviousStatus = FindingStatus.Pending, NewStatus = FindingStatus.InCorrection, Comment = "Corrección iniciada al cargar una nueva versión.", ChangedBy = ctx.User.UserId() }); finding.Status = FindingStatus.InCorrection; await db.SaveChangesAsync(ct); } var audit = await engine.ExecuteAsync(finding.TradeOperationId, AuditType.Reaudit, ctx.User.UserId(), ct); await db.Entry(finding).ReloadAsync(ct); var version = await db.OperationDocuments.Where(x => x.Id == item.DocumentId).Select(x => x.Version).SingleAsync(ct); return Results.Ok(new { message = finding.Status == FindingStatus.Resolved ? "Documento corregido correctamente. La re-auditoría no encontró inconsistencias. Hallazgo resuelto." : "Documento cargado y re-auditado.", documentVersion = version, auditId = audit.Id, findingStatus = finding.Status }); }).DisableAntiforgery();

api.MapGet("/audits", async (SaceDbContext db) => Results.Ok(await db.Audits.AsNoTracking().OrderByDescending(x => x.StartedAt).Take(100).Select(x => new { x.Id, x.Number, x.AuditType, x.Status, x.TradeOperationId, x.Period, x.StartedAt, x.CompletedAt, results = x.Results.Count }).ToListAsync()));
api.MapGet("/audits/monthly", async (string period, IMonthlyAuditRule rule, CancellationToken ct) => Results.Ok(await rule.EvaluateAsync(period, ct)));
api.MapPost("/audits/monthly", async (string period, HttpContext ctx, SaceDbContext db, IMonthlyAuditRule rule, CancellationToken ct) => { var result = await rule.EvaluateAsync(period, ct); var audit = new Audit { Number = $"AUD-{(await db.Audits.CountAsync(ct) + 1):D6}", Period = period, AuditType = AuditType.Monthly, Status = AuditStatus.Completed, CompletedAt = DateTime.UtcNow, CreatedBy = ctx.User.UserId() }; db.Audits.Add(audit); db.SystemAuditLogs.Add(Log(ctx.User.UserId(), "MONTHLY_AUDIT_EXECUTED", "Audit", audit.Id, $"Periodo {period}; regla DEMO-MONTHLY-001.")); await db.SaveChangesAsync(ct); return Results.Ok(result); });

api.MapGet("/normative-rules", async (SaceDbContext db) => Results.Ok(await db.NormativeRules.AsNoTracking().OrderBy(x => x.Code).ThenByDescending(x => x.Version).ToListAsync()));
api.MapPost("/normative-rules", async (RuleRequest request, HttpContext ctx, SaceDbContext db) => { var code = request.Code.Trim().ToUpperInvariant(); var version = await db.NormativeRules.Where(x => x.Code == code).MaxAsync(x => (int?)x.Version) ?? 0; var rule = new NormativeRule { Code = code, Name = request.Name, NormativeSource = request.NormativeSource, RuleCategory = request.RuleCategory, Description = request.Description, RuleType = request.RuleType, SourceDocument = request.SourceDocument, Article = request.Article, Section = request.Section, Subsection = request.Subsection, RuleNumber = request.RuleNumber, Annex = request.Annex, Appendix = request.Appendix, OfficialUrl = request.OfficialUrl, PublicationDate = request.PublicationDate?.ToUniversalTime(), EffectiveFrom = request.EffectiveFrom.ToUniversalTime(), EffectiveTo = request.EffectiveTo?.ToUniversalTime(), Version = version + 1, IsActive = request.IsActive, AutomationLevel = request.AutomationLevel, RequiresManualReview = request.RequiresManualReview, IsLegalRule = request.IsLegalRule, IsIncludedInLegalCompliance = request.IsIncludedInLegalCompliance, ConfigurationJson = request.ConfigurationJson }; db.NormativeRules.Add(rule); db.SystemAuditLogs.Add(Log(ctx.User.UserId(), "NORMATIVE_RULE_VERSION_CHANGED", "NormativeRule", rule.Id, $"{rule.Code} v{rule.Version}.")); await db.SaveChangesAsync(); return Results.Created($"/api/normative-rules/{rule.Id}", rule); });
api.MapPatch("/normative-rules/{id:guid}/toggle", async (Guid id, HttpContext ctx, SaceDbContext db) => { var rule = await db.NormativeRules.FindAsync(id); if (rule is null) return Results.NotFound(); rule.IsActive = !rule.IsActive; db.SystemAuditLogs.Add(Log(ctx.User.UserId(), "NORMATIVE_RULE_TOGGLED", "NormativeRule", id, $"{rule.Code} v{rule.Version}: {(rule.IsActive ? "activa" : "inactiva")}.")); await db.SaveChangesAsync(); return Results.Ok(rule); });
api.MapGet("/document-types", async (SaceDbContext db) => Results.Ok(await db.DocumentTypes.AsNoTracking().OrderBy(x => x.Name).ToListAsync()));
api.MapPatch("/document-types/{id:guid}", async (Guid id, DocumentType request, HttpContext ctx, SaceDbContext db) => { var item = await db.DocumentTypes.FindAsync(id); if (item is null) return Results.NotFound(); item.Name=request.Name; item.Description=request.Description; item.CorrectionResponsible=request.CorrectionResponsible; item.IsActive=request.IsActive; db.SystemAuditLogs.Add(Log(ctx.User.UserId(), "DOCUMENT_TYPE_UPDATED", "DocumentType", id, $"Catálogo {item.Code} actualizado.")); await db.SaveChangesAsync(); return Results.Ok(item); });
api.MapGet("/audit-log", async (string? action, DateTime? from, DateTime? to, SaceDbContext db) => { var q = db.SystemAuditLogs.AsNoTracking().Include(x => x.User).AsQueryable(); if (!string.IsNullOrWhiteSpace(action)) q = q.Where(x => x.Action.Contains(action)); if (from.HasValue) q = q.Where(x => x.Timestamp >= from); if (to.HasValue) q = q.Where(x => x.Timestamp <= to); return Results.Ok(await q.OrderByDescending(x => x.Timestamp).Take(250).Select(x => new { x.Id, x.Timestamp, user = x.User != null ? x.User.Name : "Sistema", x.Action, x.EntityType, x.EntityId, x.Details }).ToListAsync()); });

