static SystemAuditLog Log(Guid user, string action, string entity, Guid id, string details) => new() { UserId = user == Guid.Empty ? null : user, Action = action, EntityType = entity, EntityId = id.ToString(), Details = details };
static async Task<string?> ValidateRegulatoryRequest(RegulatoryRequirementRequest request,SaceDbContext db,CancellationToken ct) {
  if(string.IsNullOrWhiteSpace(request.Code)||string.IsNullOrWhiteSpace(request.Name))return "Código y nombre son obligatorios.";
  var allowedFields=new HashSet<string>([DocumentFieldCodes.TariffFraction,DocumentFieldCodes.Nico,DocumentFieldCodes.OperationType,"CUSTOMS_REGIME",DocumentFieldCodes.OriginCountry,DocumentFieldCodes.DestinationCountry,DocumentFieldCodes.CustomsOffice,DocumentFieldCodes.Description,DocumentFieldCodes.Quantity,DocumentFieldCodes.Unit,DocumentFieldCodes.CommercialValue,DocumentFieldCodes.Currency],StringComparer.OrdinalIgnoreCase);
  if(request.Conditions is null||request.Conditions.Count==0)return "Capture al menos una condición.";if(request.Conditions.Any(x=>!allowedFields.Contains(x.FieldCode)))return "La solicitud contiene un campo de condición no soportado.";
  if(request.Conditions.Any(x=>x.Operator==RegulatoryConditionOperator.NUMERIC_RANGE&&(string.IsNullOrWhiteSpace(x.ExpectedValue)||string.IsNullOrWhiteSpace(x.ExpectedValue2))))return "NUMERIC_RANGE requiere los dos límites.";
  var evidence=(request.EvidenceRequirements??[]).Select(x=>x.DocumentTypeCode.Trim().ToUpperInvariant()).Distinct().ToList();var existing=await db.DocumentTypes.Where(x=>evidence.Contains(x.Code)).Select(x=>x.Code).ToListAsync(ct);if(existing.Count!=evidence.Count)return "La solicitud contiene un tipo documental inexistente.";
  if(request.EffectiveFrom.HasValue&&request.EffectiveTo.HasValue&&request.EffectiveFrom>request.EffectiveTo)return "La vigencia final no puede ser anterior a la inicial.";return null;
}
static void ApplyRegulatoryRequest(RegulatoryRequirement item,RegulatoryRequirementRequest request) {
  ApplyRegulatoryScalars(item,request);
  foreach(var condition in request.Conditions??[])item.Conditions.Add(new RegulatoryRequirementCondition{FieldCode=condition.FieldCode.Trim().ToUpperInvariant(),Operator=condition.Operator,ExpectedValue=condition.ExpectedValue?.Trim(),ExpectedValue2=condition.ExpectedValue2?.Trim(),ConditionGroup=string.IsNullOrWhiteSpace(condition.ConditionGroup)?"DEFAULT":condition.ConditionGroup.Trim().ToUpperInvariant(),Sequence=Math.Max(1,condition.Sequence)});
  foreach(var evidence in request.EvidenceRequirements??[])item.EvidenceRequirements.Add(new RegulatoryEvidenceRequirement{DocumentTypeCode=evidence.DocumentTypeCode.Trim().ToUpperInvariant(),EvidenceRole=evidence.EvidenceRole,IsRequired=evidence.IsRequired,Description=evidence.Description?.Trim(),AlternativeGroup=evidence.AlternativeGroup?.Trim().ToUpperInvariant()});
}
static void ApplyRegulatoryScalars(RegulatoryRequirement item,RegulatoryRequirementRequest request){item.Name=request.Name.Trim();item.Description=request.Description?.Trim();item.RequirementCategory=request.RequirementCategory;item.AuthorityCode=request.AuthorityCode;item.AuthorityName=request.AuthorityName?.Trim();item.OperationScope=request.OperationScope;item.LegalBasis=request.LegalBasis?.Trim();item.OfficialSourceUrl=request.OfficialSourceUrl?.Trim();item.PublicationDate=request.PublicationDate?.ToUniversalTime();item.EffectiveFrom=request.EffectiveFrom?.ToUniversalTime();item.EffectiveTo=request.EffectiveTo?.ToUniversalTime();item.IsAutomatable=request.IsAutomatable;item.RequiresManualReview=request.RequiresManualReview;}
static void SyncRegulatoryChildren(RegulatoryRequirement item,RegulatoryRequirementRequest request,SaceDbContext db){var conditions=request.Conditions??[];for(var i=0;i<conditions.Count;i++){var source=conditions[i];var target=i<item.Conditions.Count?item.Conditions[i]:new RegulatoryRequirementCondition{RegulatoryRequirementId=item.Id};if(i>=item.Conditions.Count)item.Conditions.Add(target);target.FieldCode=source.FieldCode.Trim().ToUpperInvariant();target.Operator=source.Operator;target.ExpectedValue=source.ExpectedValue?.Trim();target.ExpectedValue2=source.ExpectedValue2?.Trim();target.ConditionGroup=string.IsNullOrWhiteSpace(source.ConditionGroup)?"DEFAULT":source.ConditionGroup.Trim().ToUpperInvariant();target.Sequence=Math.Max(1,source.Sequence);}if(item.Conditions.Count>conditions.Count){var removed=item.Conditions.Skip(conditions.Count).ToList();db.RegulatoryRequirementConditions.RemoveRange(removed);}var evidence=request.EvidenceRequirements??[];for(var i=0;i<evidence.Count;i++){var source=evidence[i];var target=i<item.EvidenceRequirements.Count?item.EvidenceRequirements[i]:new RegulatoryEvidenceRequirement{RegulatoryRequirementId=item.Id};if(i>=item.EvidenceRequirements.Count)item.EvidenceRequirements.Add(target);target.DocumentTypeCode=source.DocumentTypeCode.Trim().ToUpperInvariant();target.EvidenceRole=source.EvidenceRole;target.IsRequired=source.IsRequired;target.Description=source.Description?.Trim();target.AlternativeGroup=source.AlternativeGroup?.Trim().ToUpperInvariant();}if(item.EvidenceRequirements.Count>evidence.Count){var removed=item.EvidenceRequirements.Skip(evidence.Count).ToList();db.RegulatoryEvidenceRequirements.RemoveRange(removed);}}
static async Task Error(HttpContext context, int status, string code, string message) { context.Response.StatusCode = status; context.Response.ContentType = "application/json"; await context.Response.WriteAsJsonAsync(new ApiError(status, code, message, new { })); }

